"""A small client for the MCP endpoints of neatroots (local) and neatlogs cloud.

Both speak JSON-RPC over HTTP. This is the only place whodunit talks to them, and it uses
nothing outside the standard library.
"""

import json
import os
import urllib.error
import urllib.request

NEATROOTS = "http://localhost:4100/mcp"
NEATLOGS = "https://ingest.neatlogs.com/mcp"


class NeatError(RuntimeError):
    pass


class Mcp:
    def __init__(self, url: str = NEATROOTS, token: str | None = None, timeout: float = 60.0):
        self.url, self.token, self.timeout = url, token, timeout
        self.session: str | None = None
        self.ready = False

    def _post(self, method: str, params: dict | None = None, notify: bool = False):
        body = {"jsonrpc": "2.0", "method": method}
        if params is not None:
            body["params"] = params
        if not notify:
            body["id"] = 1
        headers = {"Content-Type": "application/json", "Accept": "application/json, text/event-stream"}
        if self.token:
            headers["Authorization"] = f"Bearer {self.token}"
        if self.session:
            headers["Mcp-Session-Id"] = self.session
        request = urllib.request.Request(self.url, json.dumps(body).encode(), headers)
        try:
            with urllib.request.urlopen(request, timeout=self.timeout) as response:
                self.session = response.headers.get("Mcp-Session-Id") or self.session
                raw = response.read().decode()
                kind = response.headers.get("Content-Type") or ""
        except urllib.error.HTTPError as exc:
            raise NeatError(f"{self.url} answered {exc.code} to {method}") from None
        except OSError as exc:
            raise NeatError(f"{self.url} is not reachable: {exc}") from None
        if notify or not raw.strip():
            return None
        if "text/event-stream" in kind:
            raw = [line[5:].strip() for line in raw.splitlines() if line.startswith("data:")][-1]
        reply = json.loads(raw)
        if "error" in reply:
            raise NeatError(f"{method} failed: {reply['error'].get('message', reply['error'])}")
        return reply.get("result")

    def call(self, tool: str, **arguments):
        """Call one tool and return its result, parsed from JSON when it is JSON."""
        if not self.ready:
            self._post("initialize", {"protocolVersion": "2025-03-26", "capabilities": {}, "clientInfo": {"name": "whodunit", "version": "0.1"}})
            self._post("notifications/initialized", {}, notify=True)
            self.ready = True
        result = self._post("tools/call", {"name": tool, "arguments": arguments}) or {}
        text = "\n".join(part.get("text", "") for part in result.get("content", []) if part.get("type") == "text")
        if result.get("isError"):
            raise NeatError(f"{tool} failed: {text[:300]}")
        try:
            return json.loads(text)
        except json.JSONDecodeError:
            return text


def select_all(mcp: Mcp, sql: str, cap: int = 5000) -> list[dict]:
    """Run a SELECT and page through it. neatroots hands back at most 200 rows per query."""
    rows: list[dict] = []
    while len(rows) < cap:
        page = mcp.call("query_sql", sql=f"{sql} limit 200 offset {len(rows)}").get("rows", [])
        rows += page
        if len(page) < 200:
            break
    return rows


def neatroots() -> Mcp:
    return Mcp(os.environ.get("NEATROOTS_MCP", NEATROOTS))


def replay_runs(mcp: Mcp, case_id: str, sha: str | None = None, limit: int = 200) -> list[dict]:
    """Runs neatroots holds for a case, newest first, each with the commit it ran on.

    The agent writes its tags into the run_info span, which is where this reads them from.
    """
    like = f"%case:{case_id}%" if sha is None else f"%commit:{sha}%case:{case_id}%"
    safe = like.replace("'", "''")
    rows = mcp.call("query_sql", sql=(
        "select r.trace_id, r.status, r.started_ms, r.total_tokens, r.prompt_tokens, r.completion_tokens, "
        "r.error_count, r.finding_count, r.input_preview, r.output_preview, s.output_preview as info "
        "from runs r join spans s on s.trace_id = r.trace_id and s.name = 'run_info' "
        f"where s.attributes like '{safe}' order by r.started_ms desc limit {int(limit)}"
    ))
    out = []
    for row in rows.get("rows", []):
        tags = []
        try:
            tags = json.loads(row.pop("info") or "{}").get("tags", [])
        except (json.JSONDecodeError, AttributeError):
            pass
        row["commit"] = next((t.split(":", 1)[1] for t in tags if t.startswith("commit:")), None)
        row["case"] = next((t.split(":", 1)[1] for t in tags if t.startswith("case:")), None)
        out.append(row)
    return out
"""One way to ask a model for text, used by the brief and the patch.

WHODUNIT_LLM picks where the question goes:

    gateway  the hackathon gateway, with LITELLM_BASE_URL and LITELLM_API_KEY from .env (default)
    own      your own key, ANTHROPIC_API_KEY from .env
    agent    a coding agent in headless mode: the command in WHODUNIT_AGENT_CMD gets the prompt
             on stdin and prints its answer
    none     no model at all; callers fall back to a template

WHODUNIT_MODEL overrides the model id for gateway and own.
"""

import json
import os
import shlex
import subprocess
import time
import urllib.error
import urllib.request

from .env import load_env

DEFAULT_MODELS = {"gateway": "claude-sonnet-4.6", "own": "claude-sonnet-5-5"}


class LlmError(RuntimeError):
    pass


def choice() -> str:
    return os.environ.get("WHODUNIT_LLM", "gateway")


def model_name() -> str:
    which = choice()
    if which == "agent":
        return "coding agent, headless"
    return os.environ.get("WHODUNIT_MODEL", DEFAULT_MODELS.get(which, "none"))


def ask(system: str, prompt: str, max_tokens: int = 1500, timeout: float = 180.0) -> str:
    which = choice()
    if which == "none":
        raise LlmError("WHODUNIT_LLM is none")
    if which == "agent":
        command = os.environ.get("WHODUNIT_AGENT_CMD")
        if not command:
            raise LlmError("WHODUNIT_AGENT_CMD is not set")
        done = subprocess.run(shlex.split(command), input=f"{system}\n\n{prompt}", capture_output=True, text=True, timeout=timeout)
        if done.returncode != 0:
            raise LlmError(f"the coding agent exited with {done.returncode}")
        return done.stdout
    load_env()
    if which == "gateway":
        base, key = os.environ.get("LITELLM_BASE_URL", ""), os.environ.get("LITELLM_API_KEY", "")
    elif which == "own":
        base, key = "https://api.anthropic.com/v1", os.environ.get("ANTHROPIC_API_KEY", "")
    else:
        raise LlmError(f"WHODUNIT_LLM={which} is not one of gateway, own, agent, none")
    if not base or not key:
        raise LlmError(f"the keys for WHODUNIT_LLM={which} are not in .env")
    body = {
        "model": model_name(), "max_tokens": max_tokens,
        "messages": [{"role": "system", "content": system}, {"role": "user", "content": prompt}],
    }
    request = urllib.request.Request(
        base.rstrip("/") + "/chat/completions", json.dumps(body).encode(),
        {"Content-Type": "application/json", "Authorization": f"Bearer {key}"},
    )
    problem = ""
    for wait in (0, 5, 20):  # a gateway hiccup should not cost a whole fix attempt
        time.sleep(wait)
        try:
            with urllib.request.urlopen(request, timeout=timeout) as response:
                reply = json.loads(response.read().decode())
            return reply["choices"][0]["message"]["content"] or ""
        except urllib.error.HTTPError as exc:
            problem = f"the model endpoint answered {exc.code}"
            if exc.code not in (408, 429, 500, 502, 503, 504, 529):
                break
        except OSError as exc:
            problem = f"the model endpoint is not reachable: {exc}"
    raise LlmError(problem)
"""The ruling: revert the culprit, or keep what it was for and patch it?

That is the owner's call, and it is asked once per kind of change. The answer is kept as a
file under rulings/ so the next case of the same kind does not ask again.
"""

import json
import re
from dataclasses import asdict, dataclass
from datetime import date
from pathlib import Path

REVERT, PATCH = "revert", "patch"

KINDS = {
    "prompt": "a change to the agent's instructions",
    "model-settings": "a change to the model or its settings",
    "dependency": "a dependency change",
    "tool-code": "a change to the code of a tool the agent calls",
    "agent-code": "a change to the agent's own code",
    "other": "a change outside the agent's code",
}


@dataclass
class Ruling:
    kind: str
    ruling: str  # revert or patch
    decided_on: str
    first_case: str
    culprit: str
    note: str = ""


def classify(diff: str, files: list[str]) -> str:
    """What kind of change the culprit made, from its diff. Rough on purpose: it only picks which standing ruling applies."""
    changed = [line[1:] for line in diff.splitlines() if line[:1] in "+-" and not line.startswith(("+++", "---"))]
    text = "\n".join(changed)
    names = " ".join(files).lower()
    if re.search(r"(pyproject\.toml|uv\.lock|requirements[\w.-]*\.txt|package(-lock)?\.json)", names) and not re.search(r"\.py\b", names):
        return "dependency"
    if re.search(r"\b(SYSTEM|PROMPT|INSTRUCTIONS)[A-Z_]*\b|system_prompt|\"role\": \"system\"", text) or "prompt" in names:
        return "prompt"
    # A reworded prompt often changes only the string lines inside it, and the name sits in the context.
    only_strings = bool(changed) and all(line.strip()[:1] in "\"'#" or line.strip()[:2] in ('f"', "f'") for line in changed if line.strip())
    if only_strings and re.search(r"\b(SYSTEM|PROMPT|INSTRUCTIONS)[A-Z_]*\b|system_prompt", diff):
        return "prompt"
    if re.search(r"\b(MODEL|temperature|max_tokens|top_p)\b", text):
        return "model-settings"
    # A tool's own lines are often context around the change, so this one reads the whole diff.
    if re.search(r"kind=\"TOOL\"|\bTOOLS\b|def call_tool\b", diff):
        return "tool-code"
    if re.search(r"\.py\b", names):
        return "agent-code"
    return "other"


def path_for(repo: str | Path, kind: str) -> Path:
    return Path(repo) / "rulings" / f"{kind}.json"


def recall(repo: str | Path, kind: str) -> Ruling | None:
    path = path_for(repo, kind)
    return Ruling(**json.loads(path.read_text())) if path.is_file() else None


def question(kind: str, subject: str, request: str | None) -> str:
    asked = f' It was asked for with: "{request.strip().splitlines()[0][:160]}"' if request else ""
    return (
        f"The culprit is {KINDS.get(kind, kind)}: \"{subject}\".{asked}\n"
        f"Revert it, or keep what it was for and patch the bug? This answer becomes the rule for every {kind} case. [revert/patch] "
    )


def decide(repo: str | Path, kind: str, case_id: str, culprit: str, subject: str, request: str | None = None,
           answer: str | None = None, ask=None) -> tuple[Ruling, bool]:
    """Return (ruling, asked). Asks only when there is no ruling for this kind yet."""
    known = recall(repo, kind)
    if known:
        return known, False
    if answer is None:
        answer = (ask or input)(question(kind, subject, request))
    answer = answer.strip().lower()
    if answer not in (REVERT, PATCH):
        raise ValueError(f"the ruling has to be revert or patch, and was {answer!r}")
    ruling = Ruling(kind=kind, ruling=answer, decided_on=date.today().isoformat(), first_case=case_id, culprit=culprit)
    path = path_for(repo, kind)
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(json.dumps(asdict(ruling), indent=1) + "\n")
    return ruling, True
"""A case: a symptom, the failing inputs, a good ref, a bad ref and a check."""

import json
import math
import os
import subprocess
import tomllib
from dataclasses import dataclass, field
from pathlib import Path


@dataclass(frozen=True)
class CaseInput:
    text: str
    expect: dict = field(default_factory=dict)  # what the check compares against, e.g. {"refunds": [...]}


@dataclass(frozen=True)
class Case:
    id: str
    symptom: str
    good: str
    bad: str
    inputs: tuple[CaseInput, ...]
    target: str = "."  # folder inside the repo that holds the agent
    build: tuple[str, ...] = ()  # run once per worktree; a failure skips the commit
    run: tuple[str, ...] = ()  # "{input}" is replaced with the input text
    check: dict = field(default_factory=lambda: {"kind": "refunds"})
    env: dict = field(default_factory=dict)
    timeout: float = 120.0
    fixed: str = ""  # the commit that fixed it, once the case is closed and kept as a regression test

    @classmethod
    def load(cls, path: str | Path) -> "Case":
        data = tomllib.loads(Path(path).read_text())
        inputs = tuple(
            CaseInput(text=i["text"], expect={k: v for k, v in i.items() if k != "text"}) for i in data.pop("inputs")
        )
        for key in ("build", "run"):
            data[key] = tuple(data.get(key, ()))
        return cls(inputs=inputs, **data)


def last_json_line(stdout: str) -> dict | None:
    """The agent prints its result as one JSON object on the last line that parses."""
    for line in reversed(stdout.strip().splitlines()):
        line = line.strip()
        if line.startswith("{"):
            try:
                return json.loads(line)
            except json.JSONDecodeError:
                continue
    return None


def _same_refunds(got: list[dict], want: list[dict]) -> bool:
    def key(r):
        return (str(r.get("order_id")), float(r.get("refunded", 0)))

    got, want = sorted(map(key, got)), sorted(map(key, want))
    return len(got) == len(want) and all(g[0] == w[0] and math.isclose(g[1], w[1], abs_tol=0.005) for g, w in zip(got, want))


def judge(case: Case, case_input: CaseInput, stdout: str, cwd: Path) -> tuple[bool, str]:
    """Return (passed, reason) for one run of the agent."""
    kind = case.check.get("kind", "refunds")
    result = last_json_line(stdout)
    if kind == "refunds":
        if result is None:
            return False, "the agent printed no JSON result"
        want = case_input.expect.get("refunds", [])
        got = result.get("refunds", [])
        if _same_refunds(got, want):
            return True, f"refunds match: {json.dumps(got)}"
        return False, f"refunds were {json.dumps(got)}, expected {json.dumps(want)}"
    if kind == "command":
        # The command gets the agent's stdout on stdin and the expectation in WHODUNIT_EXPECT. Exit 0 is a pass.
        done = subprocess.run(
            case.check["command"], input=stdout, capture_output=True, text=True, cwd=cwd, timeout=case.timeout,
            env={**os.environ, "WHODUNIT_EXPECT": json.dumps(case_input.expect)},
        )
        reason = (done.stdout.strip() or done.stderr.strip()).splitlines()[-1:] or [f"exit {done.returncode}"]
        return done.returncode == 0, reason[0]
    raise ValueError(f"check kind {kind!r} is not one of refunds, command")
"""Read keys from the repo's .env file inside the process that needs them."""

import os
from pathlib import Path


def load_env(start: str | Path = ".") -> None:
    """Put .env values into os.environ. Values already set win. Never prints anything."""
    explicit = os.environ.get("WHODUNIT_ENV")
    here = Path(start).resolve()
    candidates = [Path(explicit)] if explicit else [p / ".env" for p in (here, *here.parents)]
    path = next((p for p in candidates if p.is_file()), None)
    if path is None:
        return
    for line in path.read_text().splitlines():
        line = line.strip()
        if not line or line.startswith("#") or "=" not in line:
            continue
        key, _, value = line.partition("=")
        os.environ.setdefault(key.strip(), value.strip().strip("'\""))
"""A simulator for the lineup: how often is the right commit named, for a given replay budget?

    python -m whodunit.simulate --out eval/simulator

Each simulated case has `suspects` commits and one culprit chosen at random. A commit before
the culprit fails at `good_rate`, and the culprit and everything after it fails at `bad_rate`.
Three methods get the same case and the same budget of replays:

- statistical: the statistical bisect in whodunit.lineup.
- plain, repeated: plain bisect that replays each commit up to k times and calls it bad on the
  first failure, with k as large as the budget allows.
- plain, once: plain bisect with one replay per commit, which is what `git bisect run` does.
"""

import argparse
import json
import math
import random
from concurrent.futures import ProcessPoolExecutor
from dataclasses import asdict, dataclass
from pathlib import Path

from .lineup import FAIL, PASS, plain_bisect, statistical_bisect

RATES = (1.0, 0.8, 0.6, 0.4, 0.3, 0.2)
BUDGETS = (10, 20, 30, 40, 60, 80, 120, 160, 240, 320)
METHODS = ("statistical", "plain_repeated", "plain_once")


@dataclass
class Cell:
    method: str
    bad_rate: float
    good_rate: float
    budget: int
    suspects: int
    trials: int
    right: int = 0
    wrong: int = 0
    nobody: int = 0
    top_right: int = 0  # the most likely suspect was the culprit, whether or not anyone was named
    replays: int = 0  # total over all trials

    @property
    def accuracy(self) -> float:
        return self.right / self.trials


def one_case(method: str, suspects: int, culprit: int, bad_rate: float, good_rate: float, budget: int, rng: random.Random):
    """Returns (accused index or None, most likely suspect or None, replays used)."""
    used = 0

    def trial(position: int) -> str:
        nonlocal used
        used += 1
        return FAIL if rng.random() < (bad_rate if position >= culprit else good_rate) else PASS

    if method == "statistical":
        found = statistical_bisect(suspects, trial, budget)
        return found.culprit, None if found.note else found.remaining[0], found.replays
    steps = max(1, math.ceil(math.log2(suspects)))
    repeats = 1 if method == "plain_once" else max(1, budget // steps)

    def test(index: int) -> str:
        for _ in range(repeats):
            if trial(index) == FAIL:
                return FAIL
        return PASS

    accused = plain_bisect(suspects, test).culprit
    return accused, accused, used


def run_cell(cell: Cell, seed: int = 0) -> Cell:
    for n in range(cell.trials):
        # The culprit depends on the trial alone, so every method and budget meets the same cases.
        culprit = random.Random(f"culprit-{seed}-{n}").randrange(cell.suspects)
        rng = random.Random(f"{seed}-{cell.method}-{cell.bad_rate}-{cell.good_rate}-{cell.budget}-{n}")
        accused, top, used = one_case(cell.method, cell.suspects, culprit, cell.bad_rate, cell.good_rate, cell.budget, rng)
        cell.replays += used
        cell.top_right += top == culprit
        if accused is None:
            cell.nobody += 1
        elif accused == culprit:
            cell.right += 1
        else:
            cell.wrong += 1
    return cell


def sweep(suspects: int = 40, trials: int = 500, good_rate: float = 0.0, rates=RATES, budgets=BUDGETS, workers: int | None = None) -> list[Cell]:
    cells = [Cell(m, r, good_rate, b, suspects, trials) for r in rates for b in budgets for m in METHODS]
    with ProcessPoolExecutor(max_workers=workers) as pool:
        return list(pool.map(run_cell, cells, chunksize=4))


def to_rows(cells: list[Cell]) -> list[dict]:
    return [{**asdict(c), "accuracy": round(c.accuracy, 4), "mean_replays": round(c.replays / c.trials, 1)} for c in cells]


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description=__doc__.split("\n")[0])
    parser.add_argument("--out", default="eval/simulator")
    parser.add_argument("--suspects", type=int, default=40)
    parser.add_argument("--trials", type=int, default=500)
    args = parser.parse_args(argv)
    out = Path(args.out)
    out.mkdir(parents=True, exist_ok=True)
    results = {}
    for name, good_rate in (("clean_baseline", 0.0), ("flaky_baseline", 0.05)):
        rows = to_rows(sweep(args.suspects, args.trials, good_rate))
        results[name] = {"suspects": args.suspects, "trials": args.trials, "good_rate": good_rate, "cells": rows}
        print(f"{name}: {len(rows)} cells")
    (out / "results.json").write_text(json.dumps(results, indent=1) + "\n")
    from .chart import write_charts

    write_charts(results, out)
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
